c----------------------------------------------------------------------                
C     Taiwan SSHAC Crustal Common Functional Model  
C     Coefficients are passed from input file and are only applicable for
C     the spectral period specified in the input file. 
C     This version includes the fault mechanism term consistent for Taiwan Crustal model.

      Subroutine S04_Crustal_CF ( m, Rrup, Rjb, ztor, ftype, dip, Width, Rx, HWFlag, 
     1                   specT, lnY, sigma, iflag, cfcoefrrup, coefcountRrup )

      include 'pfrisk.h'
      
      REAL a1, a2, a3, a4, a5, a6, a7, a8, a9, a10, a11, Mc1, Mc2, a10h
      real cfcoefRrup(MAX_Atten,14)
      REAL M, specT, sigma, Rrup, Ztor, lnY, ftype
      real Rjb, dip, Width, Rx, HWFactor
      integer iflag, coefcountRrup, HWFlag
C      real period, period1 , nper, count1, count2
      
C      data period /  0.01,  0.2,   2   /   

C Find the requested spectral period and corresponding coefficients
c      nPer = 3
cC First check for the PGA case (i.e., specT=0.0) 
c      if (specT .eq. 0.0) then
c         period1    = period(1)
c         goto 1011
c      endif

 1011 continue

C     Set the Coefficients.
      a1 = cfcoefRrup(coefcountRrup,1)   
      a2 = cfcoefRrup(coefcountRrup,2)   
      a3 = cfcoefRrup(coefcountRrup,3)   
      a4 = cfcoefRrup(coefcountRrup,4)   
      a5 = cfcoefRrup(coefcountRrup,5)   
      a6 = cfcoefRrup(coefcountRrup,6)   
      a7 = cfcoefRrup(coefcountRrup,7)   
      a8 = cfcoefRrup(coefcountRrup,8)   
      a9 = cfcoefRrup(coefcountRrup,9)   
      Mc1 = cfcoefRrup(coefcountRrup,10)
      Mc2 = cfcoefRrup(coefcountRrup,11)   
      a10 = cfcoefRrup(coefcountRrup,12)
      a11 = cfcoefRrup(coefcountRrup,13)   
      a10h = cfcoefRrup(coefcountRrup,14)   

C     Compute the ground motion.
      if ( fType .gt. 0.0 ) then
        Frv = 1.0
        Fn = 0.0
      elseif ( fType .lt. 0.0 ) then
        Frv = 0.0
        Fn = 1.0
      else
        Frv = 0.0
        Fn = 0.0
      endif
      
C     Compute the Hanging Wall term if needed. 
      if (HWFlag .eq. 1) then
         call S02_SWUS_HWModel (M, Rrup, Rjb, Rx, Dip, Width, a10h, ztor, specT, HWfactor)
      else 
         HWFactor = 0.0      
      endif

C     Compute the ground motion for the given spectral period. 
      if (M .lt. Mc1) then
         lnY = a1 - a8**2*Rrup + a9*Ztor + a2*(Mc1-Mc2) + a3*(M-Mc1)
     1         + (a5+a6*(M-5))*alog(sqrt(a7*a7+Rrup*Rrup)) + a10*Frv + a11*Fn + HWFactor
      elseif (M .ge. Mc2) then
         lnY = a1 - a8**2*Rrup + a9*Ztor + a4*(M-Mc2)  
     1         + (a5+a6*(M-5))*alog(sqrt(a7*a7+Rrup*Rrup)) + a10*Frv + a11*Fn + HWFactor
      else
         lnY = a1 - a8**2*Rrup + a9*Ztor + a2*(M-Mc2) 
     1         + (a5+a6*(M-5))*alog(sqrt(a7*a7+Rrup*Rrup)) + a10*Frv + a11*Fn + HWFactor
      endif

      sigma = 0.65

C     Convert ground motion to units of gals in natural log units. 
      lnY = lnY + 6.89
      iflag = 0

      return
      end 

c----------------------------------------------------------------------                
C     Taiwan SSHAC Subduction Common Functional Model  
C     Coefficients are passed from input file and are only applicable for
C     the spectral period specified in the input file. 
C     This version includes the fault mechanism term consistent for Taiwan Subduction model.

      Subroutine S04_Subduction_CF ( m, Rrup, ztor, specT, lnY, sigma, iflag, cfcoefrrup, coefcountRrup )

      include 'pfrisk.h'
      
      REAL  a1, a2, a3, a4, a5, a6, a7, a8, a9, a10
      real cfcoefRrup(MAX_Atten,12)
      REAL M, specT, sigma, Rrup, Ztor, lnY, termmag, ftype
      real Rjb, dip, Width, Rx, HWFactor, phi, tau
      integer iflag, coefcountRrup, HWFlag, count1, count2, nper
      real period, period1, coefMechT
      
C      data period / 0.01,  0.2,   2 /   

C Find the requested spectral period and corresponding coefficients
C      nPer = 3
C First check for the PGA case (i.e., specT=0.0) 
c      if (specT .eq. 0.0) then
c         period1    = period(1)
c         goto 1011
c      endif

 1011 continue

C     Set the Coefficients.
      a1 =  cfcoefRrup(coefcountRrup,1)   
      a2 =  cfcoefRrup(coefcountRrup,2)   
      a9 =  cfcoefRrup(coefcountRrup,3)   
      a6 =  cfcoefRrup(coefcountRrup,4)   
      a4 =  cfcoefRrup(coefcountRrup,5)   
      a5 =  cfcoefRrup(coefcountRrup,6)   
      a13 = cfcoefRrup(coefcountRrup,7)   
      Mref = cfcoefRrup(coefcountRrup,8)   
      a11 = cfcoefRrup(coefcountRrup,9)   
      a3 =  cfcoefRrup(coefcountRrup,10)
      c4 =  cfcoefRrup(coefcountRrup,11)   
      dsi = cfcoefRrup(coefcountRrup,12)   


C     Compute the ground motion for the given spectral period. 
      if (M .le. Mref) then
         lnY = a1 - a6**2*Rrup + ( a2 + a3 *(M-7.8))*alog(Rrup + c4*exp(a9*(M-6)))
     1         + a4*(M-Mref) + a13*(10-M)**2 + a11*(min(Ztor,dsi)-0.5*dsi)
      elseif (M .gt. Mref) then
         lnY = a1 - a6**2*Rrup + ( a2 + a3 *(M-7.8))*alog(Rrup + c4*exp(a9*(M-6)))
     1         + a5*(M-Mref) + a13*(10-M)**2 + a11*(min(Ztor,dsi)-0.5*dsi)
      endif

      sigma = 0.65

C     Convert ground motion to units of gals in natural log units. 
      lnY = lnY + 6.89
      iflag = 0

      return
      end 

	  
c----------------------------------------------------------------------                                                             
      Subroutine S04_Crustal_CFNPP2_001 ( m, Rrup, Rjb, ztor, ftype, dip, Width, Rx, HWFlag,        
     1                                   specT, lnY, sigma, iflag )                                                                 
                                                                                                                                    
      implicit none                                                                                                                 
                                                                                                                                    
      integer MAXPER                                                                                                                
      parameter (MAXPER= 18)
      REAL Period(MAXPER), a1(MAXPER), a2(MAXPER), a3(MAXPER), a10(MAXPER),  a11(MAXPER)                                            
      REAL a4(MAXPER), a5(MAXPER), a6(MAXPER), a7(MAXPER), a8(MAXPER), a9(MAXPER)                                                   
      real Mc1(MAXPER), Mc2(MAXPER), Rrup, Ztor, HWfactor                                                                           
      REAL M, specT, sigma, Rjb, dip, Width, Rx, a10h                                                                               
      REAL period2, lnY, period1, a1T, a2T, a3T, a4T, a5T, a6T                                                                      
      REAL a7T, a8T, a9T, Mc1T, Mc2T, a10T, a11T, Fn, Frv, fType                                                                    
      integer iflag, count1, count2, nPer, i, HWFlag                                                                                
                                                                                                                                    
      data period /   0.0000,   0.0100,   0.0200,   0.0300,   0.0500,   0.0750,   0.1000,   0.1500, 
     1                0.2000,   0.2500,   0.3000,   0.4000,   0.5000,   0.7500,   1.0000,   1.5000, 
     1                2.0000,   3.0000 / 
      data a1     /   0.7404,   0.7404,   0.6973,   1.7515,   1.4921,   0.7738,   1.4651,   1.5963, 
     1                0.9441,   1.0477,   1.2493,   2.1806,   1.0787,   0.3339,   0.4219,   0.0673, 
     1               -0.2505,  -0.4842 / 
      data a2     /  -0.3329,  -0.3329,   0.0160,  -0.0365,  -0.0318,   0.0926,  -0.3085,   0.0309, 
     1               -0.2463,  -0.0064,  -0.1952,   0.3088,   0.3746,   0.7155,   0.4242,   0.5828, 
     1                0.2207,   1.4529 / 
      data a3     /   0.0482,   0.0482,  -0.0009,   0.0657,   0.0244,   0.1904,   0.1271,   0.1667, 
     1                0.6131,   0.4701,   0.8133,   0.9463,   0.8972,   0.7002,   1.1127,   1.5706, 
     1                2.0494,   2.2456 / 
      data a4     /  -0.4897,  -0.4897,  -0.3187,  -0.3297,  -0.3466,  -0.1371,  -0.4185,  -0.4827, 
     1               -0.2637,  -0.1726,  -0.0152,   0.0697,  -0.1150,  -0.3709,  -0.0891,   0.0732, 
     1                0.2533,   0.4672 / 
      data a5     /  -1.5775,  -1.5775,  -1.3856,  -1.7714,  -1.4812,  -1.0211,  -1.4521,  -1.2907, 
     1               -1.1408,  -1.2649,  -1.3133,  -1.6785,  -1.3760,  -1.1224,  -1.3476,  -1.2690, 
     1               -1.2294,  -1.3354 / 
      data a6     /   0.3248,   0.3248,   0.2686,   0.2712,   0.2354,   0.2050,   0.2619,   0.2541, 
     1                0.1800,   0.2450,   0.1904,   0.2225,   0.2076,   0.2207,   0.2258,   0.1559, 
     1                0.1012,   0.1221 / 
      data a7     /   5.3388,   5.3388,   5.5325,   7.0213,   6.1891,   3.6181,   6.8715,   7.1124, 
     1                5.2276,   3.8714,   4.9375,   8.6818,   5.2953,   5.4498,   6.3169,   7.9502, 
     1                6.7289,   9.1072 / 
      data a8     /   0.0331,   0.0331,   0.0721,   0.0280,   0.0466,   0.1209,   0.1112,   0.1214, 
     1                0.0874,   0.1014,   0.0477,   0.0238,   0.0233,   0.0486,  -0.0134,  -0.0165, 
     1               -0.0185,   0.0233 / 
      data a9     /   0.0267,   0.0267,   0.0296,   0.0182,   0.0072,  -0.0054,   0.0264,   0.0184, 
     1                0.0240,   0.0240,   0.0269,   0.0285,   0.0199,  -0.0001,   0.0207,   0.0142, 
     1                0.0240,   0.0046 / 
      data Mc1    /   5.9876,   5.9876,   6.0801,   5.8860,   6.2472,   5.4850,   6.2515,   5.5397, 
     1                5.9328,   5.3847,   5.7899,   5.8334,   5.8316,   5.6425,   5.9136,   5.9301, 
     1                6.1962,   5.8309 / 
      data Mc2    /   6.8833,   6.8833,   6.2979,   6.1850,   6.5089,   6.5558,   7.0595,   6.0446, 
     1                7.3068,   7.2137,   6.6211,   6.5678,   6.3753,   6.5167,   6.7955,   6.6889, 
     1                6.8699,   6.5234 / 
      data a10    /   0.0000,   0.0000,   0.1148,   0.1115,   0.0246,   0.0223,   0.0594,   0.1032, 
     1                0.0873,   0.1216,   0.1308,   0.2134,   0.1422,   0.2042,   0.1096,   0.1646, 
     1                0.1210,   0.1521 / 
      data a11    /  -0.1843,  -0.1843,  -0.0459,  -0.0698,  -0.1662,  -0.2027,  -0.0122,  -0.0584, 
     1               -0.0417,  -0.0699,  -0.0530,  -0.1667,  -0.1342,  -0.1327,  -0.2223,  -0.1782, 
     1               -0.0095,  -0.1214 / 
                                                                                                                                    
C Find the requested spectral period and corresponding coefficients                                                                 
      nPer =    18
C First check for the PGA case (i.e., specT=0.0)                                                                                    
      if (specT .eq. 0.0) then                                                                                                      
        period1  = period(1)                                                                                                        
        a1T      = a1(1)                                                                                                            
        a2T      = a2(1)                                                                                                            
        a3T      = a3(1)                                                                                                            
        a4T      = a4(1)                                                                                                            
        a5T      = a5(1)                                                                                                            
        a6T      = a6(1)                                                                                                            
        a7T      = a7(1)                                                                                                            
        a8T      = a8(1)                                                                                                            
        a9T      = a9(1)                                                                                                            
        Mc1T      = Mc1(1)                                                                                                          
        Mc2T      = Mc2(1)                                                                                                          
        a10T      = a10(1)                                                                                                          
        a11T      = a11(1)                                                                                                          
        goto 1011                                                                                                                   
      elseif (specT .gt. 0.0) then                                                                                                  
C Now loop over the spectral period range of the attenuation relationship.                                                          
         do i=2,nper-1                                                                                                              
            if (specT .ge. period(i) .and. specT .le. period(i+1) ) then                                                            
               count1 = i                                                                                                           
               count2 = i+1                                                                                                         
               goto 1020                                                                                                            
            endif                                                                                                                   
         enddo                                                                                                                      
      endif                                                                                                                         
                                                                                                                                    
C Selected spectral period is outside range defined by attenuaton model.                                                            
      write (*,*)                                                                                                                   
      write (*,*) 'Crustal Common Model001 Horizontal'
      write (*,*) 'attenuation model is not defined for a '                                                                         
      write (*,*) ' spectral period of: '                                                                                           
      write (*,'(a10,f10.5)') ' Period = ',specT                                                                                    
      write (*,*) 'This spectral period is outside the defined'                                                                     
      write (*,*) 'period range in the code or beyond the range'                                                                    
      write (*,*) 'of spectral periods for interpolation.'                                                                          
      write (*,*) 'Please check the input file.'                                                                                    
      write (*,*)                                                                                                                   
      stop 99                                                                                                                       
                                                                                                                                    
C Interpolate the coefficients for the requested spectral period.                                                                   
 1020 call S24_interp (period(count1),period(count2),a1(count1),a1(count2),                                                         
     +             specT,a1T,iflag)                                                                                                 
      call S24_interp (period(count1),period(count2),a2(count1),a2(count2),                                                         
     +             specT,a2T,iflag)                                                                                                 
      call S24_interp (period(count1),period(count2),a3(count1),a3(count2),                                                         
     +             specT,a3T,iflag)                                                                                                 
      call S24_interp (period(count1),period(count2),a4(count1),a4(count2),                                                         
     +             specT,a4T,iflag)                                                                                                 
      call S24_interp (period(count1),period(count2),a5(count1),a5(count2),                                                         
     +             specT,a5T,iflag)                                                                                                 
      call S24_interp (period(count1),period(count2),a6(count1),a6(count2),                                                         
     +             specT,a6T,iflag)                                                                                                 
      call S24_interp (period(count1),period(count2),a7(count1),a7(count2),                                                         
     +             specT,a7T,iflag)                                                                                                 
      call S24_interp (period(count1),period(count2),a8(count1),a8(count2),                                                         
     +             specT,a8T,iflag)                                                                                                 
      call S24_interp (period(count1),period(count2),a9(count1),a9(count2),                                                         
     +             specT,a9T,iflag)                                                                                                 
      call S24_interp (period(count1),period(count2),Mc1(count1),Mc1(count2),                                                       
     +             specT,Mc1T,iflag)                                                                                                
      call S24_interp (period(count1),period(count2),Mc2(count1),Mc2(count2),                                                       
     +             specT,Mc2T,iflag)                                                                                                
      call S24_interp (period(count1),period(count2),a10(count1),a10(count2),                                                       
     +             specT,a10T,iflag)                                                                                                
      call S24_interp (period(count1),period(count2),a11(count1),a11(count2),                                                       
     +             specT,a11T,iflag)                                                                                                
                                                                                                                                    
 1011 period1 = specT                                                                                                               
                                                                                                                                    
      if ( fType .gt. 0.0 ) then                                                                                                    
        Frv = 1.0                                                                                                                   
        Fn = 0.0                                                                                                                    
      elseif ( fType .lt. 0.0 ) then                                                                                                
        Frv = 0.0                                                                                                                   
        Fn = 1.0                                                                                                                    
      else                                                                                                                          
        Frv = 0.0                                                                                                                   
        Fn = 0.0                                                                                                                    
      endif                                                                                                                         
	                                                                                                                                   
C     Compute the Hanging Wall term if needed.                                                                                      
      a10h =   1
      if (HWFlag .eq. 1) then                                                                                                       
         call S02_SWUS_HWModel (M, Rrup, Rjb, Rx, Dip, Width, a10h, ztor, specT, HWfactor)                                          
      else                                                                                                                          
         HWFactor = 0.0                                                                                                             
      endif                                                                                                                         
	                                                                                                                                   
C     Compute the ground motion for the given spectral period.                                                                      
      if (M .lt. Mc1T) then                                                                                                         
         lnY = a1T - a8T**2*Rrup + a9T*Ztor + a2T*(Mc1T-Mc2T) + a3T*(M-Mc1T)                                                        
     1         + (a5T+a6T*(M-5))*alog(sqrt(a7T*a7T+Rrup*Rrup)) + a10T*Frv + a11T*Fn + HWFactor                                      
      elseif (M .ge. Mc2T) then                                                                                                     
         lnY = a1T - a8T**2*Rrup + a9T*Ztor + a4T*(M-Mc2T)                                                                          
     1         + (a5T+a6T*(M-5))*alog(sqrt(a7T*a7T+Rrup*Rrup)) + a10T*Frv + a11T*Fn + HWFactor                                      
      else                                                                                                                          
         lnY = a1T - a8T**2*Rrup + a9T*Ztor + a2T*(M-Mc2T)                                                                          
     1         + (a5T+a6T*(M-5))*alog(sqrt(a7T*a7T+Rrup*Rrup)) + a10T*Frv + a11T*Fn + HWFactor                                      
      endif                                                                                                                         
                                                                                                                                    
      sigma = 0.65                                                                                                                  
                                                                                                                                    
c     Convert from g to gal                                                                                                         
      lnY = lnY + 6.89                                                                                                              
                                                                                                                                    
      period2 = period1                                                                                                             
                                                                                                                                    
      return                                                                                                                        
      end                                                                                                                           
