     1                1.4760,   1.6496 / 
      data a4     /  -0.2693,  -0.2693,  -0.3197,   0.0946,  -0.1065,  -0.2190,  -0.5763,   0.0025, 
     1               -0.4107,  -0.1930,  -0.2068,   0.0519,  -0.4180,   0.1011,   0.1998,   0.1979, 
     1               -0.1293,   0.0736 / 
      data a5     /  -1.3674,  -1.3674,  -1.4271,  -1.0731,  -1.0720,  -1.2290,  -1.8054,  -0.9391, 
     1               -1.5449,  -1.4533,  -1.2650,  -1.4044,  -1.4054,  -1.4898,  -1.3635,  -1.2469, 
     1               -1.2817,  -1.2448 / 
      data a6     /   0.2436,   0.2436,   0.2021,   0.1362,   0.1365,   0.2148,   0.3221,   0.1388, 
     1                0.3057,   0.1994,   0.1876,   0.2112,   0.2802,   0.2200,   0.1714,   0.1386, 
     1                0.2188,   0.2413 / 
      data a7     /   5.9909,   5.9909,   7.5117,   5.2419,   4.6186,   4.4768,   8.0880,   2.9063, 
     1                4.2839,   7.7553,   5.8167,   3.4626,   6.5781,   4.9596,   4.2761,   5.7954, 
     1                8.1440,   7.9313 / 
      data a8     /   0.0650,   0.0650,   0.0594,   0.0867,   0.0866,   0.1002,   0.0866,   0.1038, 
     1                0.0698,   0.0699,   0.0660,   0.0438,   0.0438,  -0.0363,  -0.0317,  -0.0113, 
     1                0.0033,   0.0492 / 
      data a9     /   0.0145,   0.0145,   0.0127,  -0.0092,   0.0124,   0.0194,   0.0328,  -0.0112, 
