     1                0.1183,   0.0509,   0.0906,   0.0245,  -0.0036,   0.0333,   0.0177,   0.0272, 
     1                0.0462,   0.0327 / 
      data a9     /   0.0080,   0.0080,   0.0244,   0.0045,   0.0025,   0.0146,  -0.0025,   0.0351, 
     1                0.0319,   0.0188,   0.0056,   0.0063,   0.0049,   0.0147,   0.0067,   0.0047, 
     1                0.0083,   0.0077 / 
