        a3T      = a3(1)                                                                                                            
        a4T      = a4(1)                                                                                                            
        a5T      = a5(1)                                                                                                            
        a6T      = a6(1)                                                                                                            
        a7T      = a7(1)                                                                                                            
        a8T      = a8(1)                                                                                                            
        a9T      = a9(1)                                                                                                            
