      call S24_interp (period(count1),period(count2),a10(count1),a10(count2),                                                       
     +             specT,a10T,iflag)                                                                                                
      call S24_interp (period(count1),period(count2),a11(count1),a11(count2),                                                       
     +             specT,a11T,iflag)                                                                                                
                                                                                                                                    
 1011 period1 = specT                                                                                                               
                                                                                                                                    
      if ( fType .gt. 0.0 ) then                                                                                                    
