      if (M .lt. Mc1T) then                                                                                                         
         lnY = a1T - a8T**2*Rrup + a9T*Ztor + a2T*(Mc1T-Mc2T) + a3T*(M-Mc1T)                                                        
     1         + (a5T+a6T*(M-5))*alog(sqrt(a7T*a7T+Rrup*Rrup)) + a10T*Frv + a11T*Fn + HWFactor                                      
      elseif (M .ge. Mc2T) then                                                                                                     
         lnY = a1T - a8T**2*Rrup + a9T*Ztor + a4T*(M-Mc2T)                                                                          
     1         + (a5T+a6T*(M-5))*alog(sqrt(a7T*a7T+Rrup*Rrup)) + a10T*Frv + a11T*Fn + HWFactor                                      
