      lnY = lnY + 6.89                                                                                                              
                                                                                                                                    
      period2 = period1                                                                                                             
                                                                                                                                    
      return                                                                                                                        
      end                                                                                                                           
c----------------------------------------------------------------------                                                             
      Subroutine S04_Crustal_CFNPP3_017 ( m, Rrup, Rjb, ztor, ftype, dip, Width, Rx, HWFlag,        
     1                                   specT, lnY, sigma, iflag )                                                                 
                                                                                                                                    
      implicit none                                                                                                                 
                                                                                                                                    
      integer MAXPER                                                                                                                
      parameter (MAXPER= 18)
      REAL Period(MAXPER), a1(MAXPER), a2(MAXPER), a3(MAXPER), a10(MAXPER),  a11(MAXPER)                                            
      REAL a4(MAXPER), a5(MAXPER), a6(MAXPER), a7(MAXPER), a8(MAXPER), a9(MAXPER)                                                   
      real Mc1(MAXPER), Mc2(MAXPER), Rrup, Ztor, HWfactor                                                                           
      REAL M, specT, sigma, Rjb, dip, Width, Rx, a10h                                                                               
      REAL period2, lnY, period1, a1T, a2T, a3T, a4T, a5T, a6T                                                                      
      REAL a7T, a8T, a9T, Mc1T, Mc2T, a10T, a11T, Fn, Frv, fType                                                                    
      integer iflag, count1, count2, nPer, i, HWFlag                                                                                
                                                                                                                                    
      data period /   0.0000,   0.0100,   0.0200,   0.0300,   0.0500,   0.0750,   0.1000,   0.1500, 
     1                0.2000,   0.2500,   0.3000,   0.4000,   0.5000,   0.7500,   1.0000,   1.5000, 
     1                2.0000,   3.0000 / 
      data a1     /   1.9352,   1.9352,   0.6116,   0.9708,   1.1822,   1.6538,   1.5846,   1.0227, 
     1                2.5300,   1.8996,   2.3438,   1.7486,   1.3177,   0.7562,   0.6152,   0.1452, 
     1               -0.1901,  -1.2418 / 
      data a2     /  -0.0470,  -0.0470,   0.3043,  -0.3287,  -0.1500,  -0.3010,  -0.1510,   0.1459, 
     1               -0.0515,   0.1321,   0.2637,   0.3494,   0.7626,   0.7019,   1.0669,   0.3258, 
     1                0.8627,   1.2118 / 
      data a3     /   0.2356,   0.2356,   0.2848,   0.1334,  -0.0180,  -0.1065,   0.0329,   0.3214, 
     1                0.2880,   0.4630,   0.7450,   0.6896,   0.6955,   1.0258,   1.1515,   1.5709, 
     1                1.7427,   1.6908 / 
      data a4     /  -0.5391,  -0.5391,  -0.1393,  -0.5016,  -0.4254,  -0.2893,  -0.3101,  -0.0168, 
     1               -0.5017,  -0.4059,  -0.0767,  -0.4272,  -0.0971,  -0.0566,  -0.1400,   0.2415, 
     1                0.1329,   0.1820 / 
      data a5     /  -1.7691,  -1.7691,  -1.0416,  -1.5130,  -1.2786,  -1.5248,  -1.4271,  -0.9411, 
     1               -1.6639,  -1.5343,  -1.5552,  -1.4441,  -1.4309,  -1.2281,  -1.2509,  -1.2963, 
     1               -1.2707,  -1.1820 / 
      data a6     /   0.2753,   0.2753,   0.1511,   0.3131,   0.2451,   0.2894,   0.2560,   0.1558, 
     1                0.2555,   0.2869,   0.1934,   0.2280,   0.2507,   0.1615,   0.1860,   0.1490, 
     1                0.1412,   0.2031 / 
      data a7     /   8.8399,   8.8399,   5.3285,   6.2673,   6.0974,   6.3628,   6.1298,   3.7211, 
     1                8.8175,   7.6910,   8.9566,   7.6024,   6.6766,   4.5492,   6.7898,   5.5531, 
     1                6.1011,   3.6640 / 
      data a8     /   0.0359,   0.0359,   0.0915,   0.0853,   0.0960,   0.0750,   0.0886,   0.1102, 
     1                0.0452,   0.0757,   0.0388,   0.0341,   0.0252,   0.0119,   0.0186,  -0.0207, 
     1                0.0035,   0.0436 / 
      data a9     /   0.0191,   0.0191,   0.0029,   0.0168,   0.0015,   0.0103,   0.0145,  -0.0020, 
     1                0.0194,   0.0295,   0.0207,   0.0125,   0.0147,   0.0016,   0.0021,   0.0018, 
     1                0.0103,   0.0076 / 
      data Mc1    /   6.0055,   6.0055,   5.7151,   5.5120,   6.7464,   6.7115,   6.1981,   5.8274, 
     1                6.2989,   5.3894,   5.6663,   5.8825,   4.9545,   5.5307,   5.5840,   5.8643, 
     1                5.9595,   5.7981 / 
      data Mc2    /   6.7002,   6.7002,   6.8536,   6.9642,   6.5173,   6.3357,   6.8355,   6.8030, 
     1                6.6392,   6.4448,   6.5916,   6.8027,   6.2601,   6.5856,   6.6451,   6.5964, 
     1                6.6859,   6.7072 / 
      data a10    /   0.1478,   0.1478,   0.0980,   0.0577,   0.0717,   0.0528,   0.0812,   0.0610, 
     1                0.0217,   0.1861,   0.1329,   0.2351,   0.2524,   0.1414,   0.1695,   0.1102, 
     1                0.1500,   0.1276 / 
      data a11    /  -0.0205,  -0.0205,  -0.0578,  -0.0912,  -0.1090,  -0.1277,  -0.1046,  -0.1255, 
     1               -0.0946,  -0.0337,  -0.0862,  -0.0743,  -0.2051,  -0.1494,  -0.2246,  -0.1976, 
     1               -0.1091,  -0.0298 / 
                                                                                                                                    
C Find the requested spectral period and corresponding coefficients                                                                 
      nPer =    18
C First check for the PGA case (i.e., specT=0.0)                                                                                    
      if (specT .eq. 0.0) then                                                                                                      
        period1  = period(1)                                                                                                        
        a1T      = a1(1)                                                                                                            
        a2T      = a2(1)                                                                                                            
        a3T      = a3(1)                                                                                                            
        a4T      = a4(1)                                                                                                            
        a5T      = a5(1)                                                                                                            
        a6T      = a6(1)                                                                                                            
        a7T      = a7(1)                                                                                                            
        a8T      = a8(1)                                                                                                            
        a9T      = a9(1)                                                                                                            
        Mc1T      = Mc1(1)                                                                                                          
        Mc2T      = Mc2(1)                                                                                                          
        a10T      = a10(1)                                                                                                          
        a11T      = a11(1)                                                                                                          
        goto 1011                                                                                                                   
      elseif (specT .gt. 0.0) then                                                                                                  
C Now loop over the spectral period range of the attenuation relationship.                                                          
         do i=2,nper-1                                                                                                              
            if (specT .ge. period(i) .and. specT .le. period(i+1) ) then                                                            
               count1 = i                                                                                                           
               count2 = i+1                                                                                                         
               goto 1020                                                                                                            
            endif                                                                                                                   
         enddo                                                                                                                      
      endif                                                                                                                         
                                                                                                                                    
C Selected spectral period is outside range defined by attenuaton model.                                                            
      write (*,*)                                                                                                                   
      write (*,*) 'Crustal Common Model017 Horizontal'
      write (*,*) 'attenuation model is not defined for a '                                                                         
      write (*,*) ' spectral period of: '                                                                                           
      write (*,'(a10,f10.5)') ' Period = ',specT                                                                                    
      write (*,*) 'This spectral period is outside the defined'                                                                     
      write (*,*) 'period range in the code or beyond the range'                                                                    
      write (*,*) 'of spectral periods for interpolation.'                                                                          
      write (*,*) 'Please check the input file.'                                                                                    
      write (*,*)                                                                                                                   
      stop 99                                                                                                                       
                                                                                                                                    
C Interpolate the coefficients for the requested spectral period.                                                                   
 1020 call S24_interp (period(count1),period(count2),a1(count1),a1(count2),                                                         
     +             specT,a1T,iflag)                                                                                                 
      call S24_interp (period(count1),period(count2),a2(count1),a2(count2),                                                         
     +             specT,a2T,iflag)                                                                                                 
      call S24_interp (period(count1),period(count2),a3(count1),a3(count2),                                                         
     +             specT,a3T,iflag)                                                                                                 
      call S24_interp (period(count1),period(count2),a4(count1),a4(count2),                                                         
     +             specT,a4T,iflag)                                                                                                 
      call S24_interp (period(count1),period(count2),a5(count1),a5(count2),                                                         
     +             specT,a5T,iflag)                                                                                                 
      call S24_interp (period(count1),period(count2),a6(count1),a6(count2),                                                         
     +             specT,a6T,iflag)                                                                                                 
      call S24_interp (period(count1),period(count2),a7(count1),a7(count2),                                                         
     +             specT,a7T,iflag)                                                                                                 
      call S24_interp (period(count1),period(count2),a8(count1),a8(count2),                                                         
     +             specT,a8T,iflag)                                                                                                 
      call S24_interp (period(count1),period(count2),a9(count1),a9(count2),                                                         
     +             specT,a9T,iflag)                                                                                                 
      call S24_interp (period(count1),period(count2),Mc1(count1),Mc1(count2),                                                       
     +             specT,Mc1T,iflag)                                                                                                
      call S24_interp (period(count1),period(count2),Mc2(count1),Mc2(count2),                                                       
     +             specT,Mc2T,iflag)                                                                                                
      call S24_interp (period(count1),period(count2),a10(count1),a10(count2),                                                       
     +             specT,a10T,iflag)                                                                                                
      call S24_interp (period(count1),period(count2),a11(count1),a11(count2),                                                       
     +             specT,a11T,iflag)                                                                                                
                                                                                                                                    
 1011 period1 = specT                                                                                                               
                                                                                                                                    
      if ( fType .gt. 0.0 ) then                                                                                                    
        Frv = 1.0                                                                                                                   
        Fn = 0.0                                                                                                                    
      elseif ( fType .lt. 0.0 ) then                                                                                                
        Frv = 0.0                                                                                                                   
        Fn = 1.0                                                                                                                    
      else                                                                                                                          
        Frv = 0.0                                                                                                                   
        Fn = 0.0                                                                                                                    
      endif                                                                                                                         
	                                                                                                                                   
C     Compute the Hanging Wall term if needed.                                                                                      
      a10h =   3
      if (HWFlag .eq. 1) then                                                                                                       
         call S02_SWUS_HWModel (M, Rrup, Rjb, Rx, Dip, Width, a10h, ztor, specT, HWfactor)                                          
      else                                                                                                                          
         HWFactor = 0.0                                                                                                             
      endif                                                                                                                         
	                                                                                                                                   
C     Compute the ground motion for the given spectral period.                                                                      
      if (M .lt. Mc1T) then                                                                                                         
         lnY = a1T - a8T**2*Rrup + a9T*Ztor + a2T*(Mc1T-Mc2T) + a3T*(M-Mc1T)                                                        
     1         + (a5T+a6T*(M-5))*alog(sqrt(a7T*a7T+Rrup*Rrup)) + a10T*Frv + a11T*Fn + HWFactor                                      
      elseif (M .ge. Mc2T) then                                                                                                     
         lnY = a1T - a8T**2*Rrup + a9T*Ztor + a4T*(M-Mc2T)                                                                          
     1         + (a5T+a6T*(M-5))*alog(sqrt(a7T*a7T+Rrup*Rrup)) + a10T*Frv + a11T*Fn + HWFactor                                      
      else                                                                                                                          
         lnY = a1T - a8T**2*Rrup + a9T*Ztor + a2T*(M-Mc2T)                                                                          
     1         + (a5T+a6T*(M-5))*alog(sqrt(a7T*a7T+Rrup*Rrup)) + a10T*Frv + a11T*Fn + HWFactor                                      
      endif                                                                                                                         
                                                                                                                                    
      sigma = 0.65                                                                                                                  
                                                                                                                                    
c     Convert from g to gal                                                                                                         
      lnY = lnY + 6.89                                                                                                              
                                                                                                                                    
      period2 = period1                                                                                                             
                                                                                                                                    
      return                                                                                                                        
      end                                                                                                                           
