      Subroutine S04_SubInter_Common004 ( m, Rrup, ztor, specT, lnY, sigma, iflag )                 
                                                                                                                                    
      implicit none                                                                                                                 
                                                                                                                                    
      integer MAXPER                                                                                                                
      parameter (MAXPER= 20)
      REAL Period(MAXPER), a1(MAXPER), a2(MAXPER), a3(MAXPER),  a11(MAXPER), dsi(MAXPER)                                            
      REAL a4(MAXPER), a5(MAXPER), a6(MAXPER), c4(MAXPER), a9(MAXPER), a13(MAXPER)                                                  
      real Mref(MAXPER), Rrup, Ztor                                                                                                 
      REAL M, specT, sigma                                                                                                          
      REAL period2, lnY, period1, a1T, a2T, a3T, a4T, a5T, a6T                                                                      
      REAL c4T, a9T, MrefT, dsiT, a11T, a13T                                                                                        
      integer iflag, count1, count2, nPer, i                                                                                        
                                                                                                                                    
      data period /   0.0000,   0.0100,   0.0200,   0.0300,   0.0500,   0.0750,   0.1000,   0.1500, 
     1                0.2000,   0.2500,   0.3000,   0.4000,   0.5000,   0.7500,   1.0000,   1.5000, 
     1                2.0000,   3.0000,   4.0000,   5.0000 / 
      data a1     /   4.1709,   4.1709,   4.9764,   3.1720,   3.0000,   4.7462,   4.9458,   5.4429, 
     1                5.9805,   5.0874,   3.1962,   4.3225,   3.9274,   4.1246,   3.8796,   1.2658, 
     1                1.7846,   0.1634,  -1.2191,  -1.3407 / 
      data a2     /  -1.4995,  -1.4995,  -1.5474,  -0.9924,  -0.9994,  -1.5280,  -1.4522,  -1.3910, 
     1               -1.6727,  -1.4197,  -1.0755,  -1.3798,  -1.1326,  -1.0095,  -1.2272,  -0.6104, 
     1               -0.9006,  -0.5060,  -0.5081,  -0.4199 / 
      data a9     /   0.1508,   0.1508,   0.3481,   0.4000,   0.0531,   0.1501,   0.0406,   0.2913, 
     1                0.0241,   0.2628,   0.2339,   0.1973,   0.3006,   0.6257,   0.2908,   0.2349, 
     1                0.3382,   0.2626,   0.2327,   0.1362 / 
      data a6     /   0.0421,   0.0421,   0.0567,   0.0376,  -0.0520,   0.0307,  -0.0357,   0.0522, 
     1                0.0425,   0.0549,   0.0309,   0.0040,   0.0276,   0.0870,   0.0836,  -0.0551, 
     1                0.0499,  -0.0723,  -0.0536,  -0.0743 / 
      data a4     /   0.1240,   0.1240,   0.6650,   0.1694,  -0.1014,   0.2520,   0.3041,   0.4696, 
     1                0.5758,   0.2537,   0.2127,   0.6252,   0.5837,   0.6503,   0.9178,   0.7030, 
     1                0.9870,   0.1776,   0.6910,   0.5905 / 
      data a5     /  -0.1628,  -0.1628,   0.3450,  -0.1731,  -0.5744,  -0.2954,  -0.1222,  -0.0628, 
     1                0.1489,   0.4162,  -0.1122,  -0.1183,   0.3886,  -0.1247,   0.3388,  -0.2902, 
     1                0.2935,  -0.1889,  -0.0841,  -0.2321 / 
      data a13    /  -0.0487,  -0.0487,  -0.0164,  -0.0593,  -0.0579,  -0.0356,  -0.0315,  -0.0455, 
     1               -0.0515,  -0.1023,  -0.0770,  -0.0154,  -0.0367,  -0.0687,  -0.0483,  -0.0451, 
     1               -0.0630,  -0.1201,  -0.0741,  -0.0948 / 
      data Mref   /   7.4391,   7.4391,   7.6755,   8.3066,   7.6682,   7.1986,   7.6523,   7.9024, 
     1                6.8855,   6.7784,   6.5689,   7.9570,   7.8407,   8.1004,   7.3863,   8.4821, 
     1                7.4299,   7.2250,   7.0655,   7.3654 / 
      data a11    /   0.0080,   0.0080,   0.0080,   0.0178,   0.0164,   0.0329,   0.0283,   0.0233, 
     1                0.0196,   0.0094,   0.0153,   0.0142,   0.0176,   0.0083,   0.0029,  -0.0003, 
     1               -0.0035,   0.0036,  -0.0017,   0.0045 / 
      data a3     /   0.1107,   0.1107,   0.1120,   0.1418,   0.1754,   0.1446,   0.1080,   0.0961, 
     1                0.0837,   0.0209,   0.0973,   0.0999,   0.0661,   0.1153,   0.0623,   0.1003, 
     1                0.0906,   0.1556,   0.1327,   0.1861 / 
      data c4     /  11.6599,  11.6599,  12.6336,   5.9709,   0.3682,   7.5520,   5.5650,   9.6891, 
     1               14.9494,   8.8550,   0.2854,   6.0602,  12.5932,  15.5632,  14.6792,   4.6890, 
     1               11.2752,   6.1870,   4.3732,   6.5493 / 
      data dsi    /  45.0451,  45.0451,  57.3379,  84.7685,  80.9974,  56.3246,  67.6608,  59.1851, 
     1               38.5765,  58.5691,  47.5723,  43.1105,  41.7023,  59.0312,  59.8683,  57.6630, 
     1               56.5577,  69.5363,  61.3916, 100.9779 / 
                                                                                                                                    
C Find the requested spectral period and corresponding coefficients                                                                 
      nPer =    20
C First check for the PGA case (i.e., specT=0.0)                                                                                    
      if (specT .eq. 0.0) then                                                                                                      
         period1  = period(1)                                                                                                       
         a1T   = a1(1)                                                                                                              
         a2T   = a2(1)                                                                                                              
         a3T   = a3(1)                                                                                                              
         a4T   = a4(1)                                                                                                              
         a5T   = a5(1)                                                                                                              
         a6T   = a6(1)                                                                                                              
         a9T   = a9(1)                                                                                                              
         a11T  = a11(1)                                                                                                             
         a13T  = a13(1)                                                                                                             
         c4T   = c4(1)                                                                                                              
         dsiT  = dsi(1)                                                                                                             
         MrefT = Mref(1)                                                                                                            
         goto 1011                                                                                                                  
      elseif (specT .gt. 0.0) then                                                                                                  
C Now loop over the spectral period range of the attenuation relationship.                                                          
         do i=2,nper-1                                                                                                              
            if (specT .ge. period(i) .and. specT .le. period(i+1) ) then                                                            
               count1 = i                                                                                                           
               count2 = i+1                                                                                                         
               goto 1020                                                                                                            
            endif                                                                                                                   
         enddo                                                                                                                      
      endif                                                                                                                         
                                                                                                                                    
C Selected spectral period is outside range defined by attenuaton model.                                                            
      write (*,*)                                                                                                                   
      write (*,*) 'Sub-Inter Common Model004 Horizontal'
      write (*,*) 'attenuation model is not defined for a '                                                                         
      write (*,*) ' spectral period of: '                                                                                           
      write (*,'(a10,f10.5)') ' Period = ',specT                                                                                    
      write (*,*) 'This spectral period is outside the defined'                                                                     
      write (*,*) 'period range in the code or beyond the range'                                                                    
      write (*,*) 'of spectral periods for interpolation.'                                                                          
      write (*,*) 'Please check the input file.'                                                                                    
      write (*,*)                                                                                                                   
      stop 99                                                                                                                       
                                                                                                                                    
C Interpolate the coefficients for the requested spectral period.                                                                   
 1020 call S24_interp (period(count1),period(count2),a1(count1),a1(count2),                                                         
     +                 specT, a1T  ,iflag)                                                                                          
      call S24_interp (period(count1),period(count2),a2(count1),a2(count2),                                                         
     +                 specT, a2T  ,iflag)                                                                                          
      call S24_interp (period(count1),period(count2),a3(count1),a3(count2),                                                         
     +                 specT, a3T  ,iflag)                                                                                          
      call S24_interp (period(count1),period(count2),a4(count1),a4(count2),                                                         
     +                 specT, a4T  ,iflag)                                                                                          
      call S24_interp (period(count1),period(count2),a5(count1),a5(count2),                                                         
     +                 specT, a5T  ,iflag)                                                                                          
      call S24_interp (period(count1),period(count2),a6(count1),a6(count2),                                                         
     +                 specT, a6T  ,iflag)                                                                                          
      call S24_interp (period(count1),period(count2),a9(count1),a9(count2),                                                         
     +                 specT, a9T  ,iflag)                                                                                          
      call S24_interp (period(count1),period(count2),a11(count1),a11(count2),                                                       
     +                 specT, a11T ,iflag)                                                                                          
      call S24_interp (period(count1),period(count2),a13(count1),a13(count2),                                                       
     +                 specT, a13T ,iflag)                                                                                          
      call S24_interp (period(count1),period(count2),c4(count1),c4(count2),                                                         
     +                 specT, c4T  ,iflag)                                                                                          
      call S24_interp (period(count1),period(count2),dsi(count1),dsi(count2),                                                       
     +                 specT, dsiT ,iflag)                                                                                          
      call S24_interp (period(count1),period(count2),Mref(count1),Mref(count2),                                                     
     +                 specT, MrefT,iflag)                                                                                          
                                                                                                                                    
 1011 period1 = specT                                                                                                               
                                                                                                                                    
C     Set Constant Terms                                                                                                            
                                                                                                                                    
C     Compute the ground motion for the given spectral period.                                                                      
      if (M .le. MrefT) then                                                                                                        
         lnY = a1T - a6T**2*Rrup + ( a2T + a3T *(M-7.8))*alog(Rrup + c4T*exp(a9T*(M-6)))                                            
     1         + a4T*(M-MrefT) + a13T*(10-M)**2 + a11T*(min(Ztor,dsiT)-0.5*dsiT)                                                    
      elseif (M .gt. MrefT) then                                                                                                    
         lnY = a1T - a6T**2*Rrup + ( a2T + a3T *(M-7.8))*alog(Rrup + c4T*exp(a9T*(M-6)))                                            
     1         + a5T*(M-MrefT) + a13T*(10-M)**2 + a11T*(min(Ztor,dsiT)-0.5*dsiT)                                                    
      endif                                                                                                                         
                                                                                                                                    
      sigma = 0.65                                                                                                                  
                                                                                                                                    
c     Convert from g to gal                                                                                                         
      lnY = lnY + 6.89                                                                                                              
                                                                                                                                    
      period2 = period1                                                                                                             
                                                                                                                                    
      return                                                                                                                        
      end                                                                                                                           
                                                                                                                                    
